import Cocoa
import WebKit
import Foundation
final class Launcher:NSObject,NSApplicationDelegate,WKNavigationDelegate {
 let win=NSWindow(contentRect:NSRect(x:0,y:0,width:500,height:780),styleMask:[.titled,.closable,.miniaturizable,.resizable],backing:.buffered,defer:false)
 let status=NSTextField(labelWithString:"Подготовка LaLune…")
 var token=""; var proxy:Process?; var startedBackend=false; var finishing=false; var localPort=0; var web:WKWebView?
 func applicationDidFinishLaunching(_ n:Notification) {win.title="LaLune";win.minSize=NSSize(width:350,height:500);win.center(); status.frame=NSRect(x:20,y:360,width:460,height:30);status.alignment = .center;status.font=NSFont.systemFont(ofSize:15);win.contentView?.addSubview(status);win.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true);DispatchQueue.global().async{self.start()}}
 func applicationShouldTerminateAfterLastWindowClosed(_ s:NSApplication)->Bool {true}
 func applicationWillTerminate(_ n:Notification){cleanup()}
 func setStatus(_ s:String){DispatchQueue.main.async{self.status.stringValue=s}}
 func request(_ path:String,_ method:String="GET")->Bool{var r=URLRequest(url:URL(string:"http://127.0.0.1:1062"+path)!);r.httpMethod=method;r.setValue(token,forHTTPHeaderField:"X-LaLune-Token");r.timeoutInterval=3;let sem=DispatchSemaphore(value:0);var ok=false;URLSession.shared.dataTask(with:r){_,res,_ in ok=(res as? HTTPURLResponse)?.statusCode==200;sem.signal()}.resume();_=sem.wait(timeout:.now()+4);return ok}
 func quote(_ s:String)->String{"'"+s.replacingOccurrences(of:"'",with:"'\\''")+"'"}
 func fail(_ s:String){DispatchQueue.main.async{self.status.stringValue=s;let a=NSAlert();a.messageText="LaLune не запущен";a.informativeText=s;a.runModal()}}
 func start(){let base=FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(".la-lune");try? FileManager.default.createDirectory(at:base,withIntermediateDirectories:true,attributes:[.posixPermissions:0o700]);let file=base.appendingPathComponent("native-api-token");if let t=try? String(contentsOf:file,encoding:.utf8),t.count>=32 {token=t.trimmingCharacters(in:.whitespacesAndNewlines)} else {token=UUID().uuidString+UUID().uuidString;do{try token.write(to:file,atomically:true,encoding:.utf8);try FileManager.default.setAttributes([.posixPermissions:0o600],ofItemAtPath:file.path)}catch{fail("Не удалось создать ключ доступа к службе.");return}}
 let resources=Bundle.main.resourceURL!;if !request("/ping"){setStatus("Для запуска службы нужен пароль администратора.");let binary=resources.appendingPathComponent("lalune-backend").path;let command="HOME=\(quote(NSHomeDirectory())) LALUNE_API_TOKEN=\(quote(token)) \(quote(binary)) >/tmp/lalune-native-backend.log 2>&1 &";let escaped=command.replacingOccurrences(of:"\\",with:"\\\\").replacingOccurrences(of:"\"",with:"\\\"");var error:NSDictionary?;NSAppleScript(source:"do shell script \"\(escaped)\" with administrator privileges")?.executeAndReturnError(&error);if let error=error{fail("Служба не запущена: \(error["NSAppleScriptErrorMessage"] ?? "отменено")");return};startedBackend=true;for _ in 0..<20{if request("/ping"){break};Thread.sleep(forTimeInterval:0.5)};if !request("/ping"){fail("Служба не отвечает. Проверьте /tmp/lalune-native-backend.log");return}}
 setStatus("Запуск интерфейса…");let session=UUID().uuidString+UUID().uuidString;let pipe=Pipe();let p=Process();p.executableURL=URL(fileURLWithPath:"/usr/bin/python3");p.arguments=[resources.appendingPathComponent("proxy.py").path,resources.appendingPathComponent("web").path,session,"0"];p.standardOutput=pipe;p.standardError=FileHandle.nullDevice;do{try p.run()}catch{fail("Не удалось запустить интерфейс: \(error.localizedDescription)");return};proxy=p;let text=String(data:pipe.fileHandleForReading.availableData,encoding:.utf8)?.trimmingCharacters(in:.whitespacesAndNewlines) ?? "";guard let port=Int(text) else {fail("Не удалось запустить локальный сервер.");return};localPort=port
 DispatchQueue.main.async{let view=WKWebView(frame:self.win.contentView!.bounds);view.autoresizingMask=[.width,.height];view.navigationDelegate=self;self.win.contentView?.addSubview(view);self.web=view;view.load(URLRequest(url:URL(string:"http://127.0.0.1:\(port)/launch/\(session)")!));self.win.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 }
 func webView(_ webView:WKWebView,decidePolicyFor action:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){guard let u=action.request.url else {decisionHandler(.cancel);return};if u.host == "127.0.0.1" && u.port == localPort {decisionHandler(.allow)}else if action.navigationType == .linkActivated && ["https","http"].contains(u.scheme ?? ""){NSWorkspace.shared.open(u);decisionHandler(.cancel)}else{decisionHandler(.cancel)}}
 func cleanup(){if finishing{return};finishing=true;if let p=proxy,p.isRunning{p.terminate()};if startedBackend{_=request("/shutdown","POST")}}
}
let app=NSApplication.shared;let delegate=Launcher();app.delegate=delegate;app.setActivationPolicy(.regular);app.run()
